parameters.jsCode:
const rawText = $input.first().json.content.parts[0].text;
const parsed = JSON.parse(rawText);

return [
  {
    json: {
      lead_score: Number(parsed.score || 0),
      lead_tier: parsed.tier || 'Cold',
      ai_confidence: parsed.confidence || 'Low',
      ai_summary: parsed.summary || '',
      ai_reasons: Array.isArray(parsed.reasons) ? parsed.reasons.join(' | ') : '',
      recommended_action: parsed.recommended_action || ''
    }
  }
];

const data = $input.first().json;

let email = (data.email || '').trim().toLowerCase();
let website = (data.website || '').trim().toLowerCase();

website = website
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/$/, '');

return [
  {
    json: {
      first_name: (data.firstName || data.first_name || '').trim(),
      last_name: (data.lastName || data.last_name || '').trim(),
      full_name: (data.full_name || `${data.firstName || ''} ${data.lastName || ''}`).trim(),
      email,
      phone: (data.phone || '').trim(),
      company: (data.company || '').trim(),
      website,
      job_title: (data.jobTitle || data.job_title || '').trim(),
      country: (data.country || '').trim(),
      message: (data.message || '').trim(),
      source: (data.source || 'Website Form').trim(),
      created_at: data.created_at || new Date().toISOString()
    }
  }
];
